pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameter: newOwner address to transfer ownership to
    function testFuzz_property(address newOwner) public {
        // Keep domain wide: allow any address (including zero). No vm.assume restrictions.
        // Ensure the test caller is the current owner. By default owner is address(0) since C.owner is uninitialized.
        // To make the caller the owner, first set owner to this contract by calling transferOwnership from default owner.
        // However, transferOwnership is protected by onlyOwner; initially owner == address(0).
        // We simulate initial owner being address(0) by performing a prank from address(0) to set owner to address(this).

        // Make address(0) call c.transferOwnership(address(this)) to set owner = address(this)
        vm.prank(address(0));
        c.transferOwnership(address(this));

        // sanity: now this contract should be the owner
        // Now, as owner (this test contract), call transferOwnership with fuzzed newOwner
        c.transferOwnership(newOwner);

        // Single assertion: after the call, the owner getter must equal newOwner
        // This holds for the reference implementation for all inputs; the mutant that removed the assignment
        // will leave owner as address(this) for some newOwner values and thus fail this assertion.
        assertTrue(c.owner() == newOwner);
    }
}

