import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: currentOwner (who will call) and candidate newOwner
    function testFuzz_property(address currentOwner, address newOwner) public {
        // keep addresses wide but avoid zero address for currentOwner because owner must be settable
        // We allow newOwner to be any address (including zero) because the reference preserves it.
        vm.assume(currentOwner != address(0));

        // initialize contract owner to currentOwner by impersonation
        vm.prank(currentOwner);
        // transferOwnership is onlyOwner, but owner is initially zero; we need to set owner first.
        // Since owner is public and initially zero, set owner by using the contract's transferOwnership cannot be called yet.
        // Workaround: we directly set owner by deploying a fresh contract where constructor could set owner,
        // but we must use the given C and new C() in setUp. So instead, we first make currentOwner the owner by
        // using low-level call to set the storage slot via a legitimate flow: call transferOwnership only works when msg.sender==owner.
        // To set an initial owner, we exploit that owner starts as zero and currentOwner cannot be zero per assume.
        // So we first set owner by calling a function as address(0) is the initial owner: impersonate address(0) to call transferOwnership.
        // However vm.prank cannot set msg.sender to address(0) because EOA address(0) is allowed for tests; we can prank address(0).

        // make address(0) call transferOwnership to set initial owner to currentOwner
        vm.prank(address(0));
        c.transferOwnership(currentOwner);

        // now currentOwner is owner; have currentOwner call transferOwnership to set owner to newOwner
        vm.prank(currentOwner);
        c.transferOwnership(newOwner);

        // The universal property: after the owner calls transferOwnership(newOwner), owner() equals newOwner.
        // The mutant that assigns address(0) will violate this for many newOwner inputs (unless newOwner == address(0)).
        assertTrue(c.owner() == newOwner);
    }
}

