contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: currentOwner (who will be the caller) and newOwner (the target)
    function testFuzz_property(address currentOwner, address newOwner) public {
        // admissible domain: owner and newOwner are arbitrary addresses
        // but require currentOwner != address(0) to be a meaningful EOA caller
        vm.assume(currentOwner != address(0));

        // Arrange: set the contract's owner to currentOwner by having the deployer (test) set owner directly.
        // The reference contract C has public owner but no constructor; however transferOwnership is onlyOwner.
        // To make currentOwner the owner, we first set the test runner as owner by calling transferOwnership from the initial owner.
        // At deployment time, owner is zero address in the provided C; calling transferOwnership requires onlyOwner, so
        // we need to first set owner to address(this) via low-level initialization: we simulate that by using vm.prank on address(0)
        // but we cannot call from address(0). Instead, we will rely on the fact that calling transferOwnership requires current owner,
        // so we will directly set the owner storage by performing a legitimate sequence accepted in the reference: if owner is zero,
        // only owner (zero) can call transferOwnership. Since no one controls address(0), we instead avoid that path by first
        // checking if owner is zero; if so, we set owner to address(this) by calling transferOwnership only if address(this) is owner.
        // To keep things simple and robust across reference/mutant, we'll ensure current owner is address(this) by exploiting that
        // at deployment owner is zero but transferOwnership is onlyOwner; the only way to set a non-zero owner in a black-box test
        // is to bypass via impersonation: use vm.prank(address(0)) to behave as if msg.sender == address(0) when owner==address(0).
        // This is allowed: vm.prank lets us set msg.sender to any address. That models the EOA that controls address(0).

        // If contract currently has owner == address(0), impersonate address(0) to set owner to currentOwner.
        if (c.owner() == address(0)) {
            vm.prank(address(0));
            // This call will succeed on the reference because owner == address(0) and msg.sender == address(0)
            c.transferOwnership(currentOwner);
            // Now owner should be currentOwner on the reference.
        } else {
            // If owner already non-zero, we need to make sure currentOwner is the owner; only proceed when currentOwner equals c.owner()
            // Restrict to admissible domain where currentOwner equals the contract's owner in this branch.
            vm.assume(currentOwner == c.owner());
        }

        // Now msg.sender must be currentOwner to exercise transferOwnership
        vm.prank(currentOwner);
        c.transferOwnership(newOwner);

        // The universal property: after a transferOwnership called by the current owner, owner() equals the supplied newOwner.
        // This holds for the reference for all admissible inputs; the mutant sets owner to address(0) for some inputs and will fail this assertion.
        assertTrue(c.owner() == newOwner);
    }
}

