pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor is the candidate caller who will attempt to transfer ownership
    function testFuzz_property(address actor) public {
        // keep actor wide; avoid zero-address as a trivial edge for ownership setting if desired
        vm.assume(actor != address(0));

        // capture initial owner
        address initialOwner = c.owner();

        // If actor is not the current owner, then calling transferOwnership(actor) MUST NOT change owner.
        // We drive the call as actor.
        vm.prank(actor);
        bool ok;
        try c.transferOwnership(actor) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, read the owner via the public getter. The invariant we assert:
        // If actor != initialOwner, then owner must remain initialOwner (onlyOwner enforced).
        // This holds for the reference contract for ALL inputs; the mutant that drops the require
        // will allow some actor != initialOwner to become owner, violating this assertion.
        address post = c.owner();
        if (actor != initialOwner) {
            assertTrue(post == initialOwner);
        } else {
            // If actor is the owner, transferOwnership may succeed and change owner to actor (no-op)
            // but owner must remain a valid address; we simply assert owner is non-zero to keep a single assert
            assertTrue(post != address(0));
        }
    }
}

